v8:item.v8:content:
ДозаполнитьШапкуЧека(СвойстваОбъекта, ДопПараметры, Объект);
Объект.СуммаВключаетНДС = Истина;
Объект.КассовыйУзел = ДопПараметры.УзелОбмена;
// Зафиксируем чек в таблице чеков.
НоваяСтрока = ДопПараметры.ТаблицаЧековОбщепита.Добавить();
НоваяСтрока.ДатаДокумента = СвойстваОбъекта.Дата;
НоваяСтрока.Объект = Объект;
ДопПараметры.ЧекиНаПроведение.Добавить(СвойстваОбъекта.Ссылка);
